import { createServer } from 'node:http'
import { after, before, describe, it } from 'node:test'
import assert from 'node:assert/strict'
import { http, HttpResponse } from 'msw'
import { setupServer } from 'msw/node'
import { createApp } from '../src/app.mjs'
import { createPricingClient } from '../src/pricing-client.mjs'

const prices = { 'http://pricing.test': { A: 30, B: 10.5, C: 100, D: 100.5 } }
const pricingApi = setupServer(
  http.get('http://pricing.test/prices/:sku', ({ params }) => HttpResponse.json({ price: prices['http://pricing.test'][params.sku] })),
)
let server, base

before(async () => {
  pricingApi.listen({ onUnhandledFrame: 'error' })
  server = createServer(createApp({ pricing: createPricingClient('http://pricing.test') }))
  await new Promise((r) => server.listen(0, '127.0.0.1', r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => { pricingApi.close(); server.close() })

const post = (body, raw = false) => fetch(`${base}/orders`, { method: 'POST', body: raw ? body : JSON.stringify(body) })
const json = async (res) => [res.status, res.headers.get('content-type'), await res.json()]

describe('POST /orders', () => {
  it('creates an order without discount at or below 100, ids sequential from 1', async () => {
    const items = [{ sku: 'C', qty: 1 }]
    assert.deepEqual(await json(await post({ items })), [201, 'application/json', { id: '1', items, total: 100 }])
  })

  it('applies 10% discount above 100', async () => {
    const items = [{ sku: 'A', qty: 4 }]
    assert.deepEqual(await json(await post({ items })), [201, 'application/json', { id: '2', items, total: 108 }])
  })

  it('floors the total', async () => {
    const items = [{ sku: 'B', qty: 1 }]
    assert.deepEqual((await json(await post({ items })))[2], { id: '3', items, total: 10 })
    const big = [{ sku: 'D', qty: 1 }] // 100.5 -> 90.45 -> 90
    assert.deepEqual((await json(await post({ items: big })))[2], { id: '4', items: big, total: 90 })
  })

  it('echoes items unchanged, including extra fields', async () => {
    const items = [{ sku: 'B', qty: 2, note: 'x' }]
    assert.deepEqual((await json(await post({ items })))[2], { id: '5', items, total: 21 })
  })

  for (const [name, body, raw] of [
    ['invalid JSON', '{nope', true],
    ['missing items', {}, false],
    ['empty items', { items: [] }, false],
    ['items not an array', { items: 'A' }, false],
    ['empty body (treated as {})', '', true],
  ]) {
    it(`400 for ${name}`, async () => {
      assert.deepEqual(await json(await post(body, raw)), [400, 'application/json', { error: 'items required' }])
    })
  }

  it('does not consume an id on a rejected request', async () => {
    const items = [{ sku: 'C', qty: 1 }]
    assert.equal((await json(await post({ items })))[2].id, '6')
  })
})

describe('GET /orders/:id', () => {
  it('returns a stored order', async () => {
    assert.deepEqual(await json(await fetch(`${base}/orders/2`)), [200, 'application/json', { id: '2', items: [{ sku: 'A', qty: 4 }], total: 108 }])
  })

  it('unknown id', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
    assert.deepEqual(await json(await fetch(`${base}/orders/999`)), [200, 'application/json', { error: 'not found' }])
  })
})

describe('other routes', () => {
  for (const [method, path] of [['GET', '/orders'], ['GET', '/nope'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/orders/1/extra']]) {
    it(`${method} ${path} -> 404 no route`, async () => {
      assert.deepEqual(await json(await fetch(`${base}${path}`, { method })), [404, 'application/json', { error: 'no route' }])
    })
  }
})
